param([string]$RepositoryRoot=(Join-Path $PSScriptRoot '..'),[string]$OutputRoot=(Join-Path $PSScriptRoot '../.build/capture-fault'))
$ErrorActionPreference='Stop';$package=Join-Path $RepositoryRoot 'package';$run=Join-Path $OutputRoot ([Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $run -Force|Out-Null
$source=@'
using System;using System.IO;using System.Drawing;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using NativeVideo;
public static class CaptureFaultChecks {
 static async Task Ready(BrowserHost browser,string profile){await browser.Start(profile);browser.View.CoreWebView2.NavigateToString("<!doctype html><html><body style='background:#123456'><div style='width:128px;height:64px;background:red'>self-generated capture fixture</div></body></html>");await browser.Wait("document.body&&document.body.textContent.includes('self-generated')",5000);}
 static async Task Run(string run){int ownedPid;string failure="";double failedSeconds;bool firstCompleted=false;using(var browser=new BrowserHost(1280,720)){await Ready(browser,Path.Combine(run,"failed-profile"));ownedPid=checked((int)browser.View.CoreWebView2.BrowserProcessId);File.WriteAllBytes(Path.Combine(run,"before.png"),await browser.CaptureFrame("png"));await browser.Eval("globalThis.__gpuDomBeginCapture=()=>{};globalThis.__gpuDomEndCapture=()=>{}");string dom=await browser.CaptureDomOverlayPngBase64();if(dom.Length<100)throw new Exception("DOM capture produced no PNG");var pending=browser.CaptureFrame("png");var watch=Stopwatch.StartNew();Process.GetProcessById(ownedPid).Kill();try{if(await Task.WhenAny(pending,Task.Delay(5000))!=pending)throw new TimeoutException("Native capture did not fail within 5s of owned browser death");await pending;firstCompleted=true;await Task.Delay(200);await browser.CaptureFrame("png");}catch(TimeoutException){throw;}catch(Exception e){failure=e.GetType().Name+": "+e.Message;}if(failure.Length==0)throw new Exception("Dead browser still accepted capture");failedSeconds=watch.Elapsed.TotalSeconds;if(failedSeconds>=5)throw new Exception("Capture failure was not prompt");}
 using(var fresh=new BrowserHost(1280,720)){await Ready(fresh,Path.Combine(run,"fresh-profile"));byte[] png=await fresh.CaptureFrame("png"),jpeg=await fresh.CaptureFrame("jpeg");if(png.Length<100||jpeg.Length<100)throw new Exception("Fresh browser capture failed");using(var image=new Bitmap(new MemoryStream(png)))using(var before=new Bitmap(Path.Combine(run,"before.png"))){foreach(var point in new[]{new Point(1000,500),new Point(20,20)})if(image.GetPixel(point.X,point.Y).ToArgb()!=before.GetPixel(point.X,point.Y).ToArgb())throw new Exception("Fresh capture pixels differ from pre-fault native capture");}File.WriteAllBytes(Path.Combine(run,"after.png"),png);File.WriteAllBytes(Path.Combine(run,"after.jpg"),jpeg);await fresh.Eval("globalThis.__gpuDomBeginCapture=()=>{};globalThis.__gpuDomEndCapture=()=>{}");string dom=await fresh.CaptureDomOverlayPngBase64();if(dom.Length<100)throw new Exception("Fresh DOM capture failed");File.WriteAllBytes(Path.Combine(run,"after-dom.png"),Convert.FromBase64String(dom));J.Write(Path.Combine(run,"result.json"),J.O("passed",true,"ownedBrowserPid",ownedPid,"firstCaptureCompletedBeforeDeath",firstCompleted,"failure",failure,"failureSeconds",failedSeconds,"freshPngBytes",png.Length,"freshJpegBytes",jpeg.Length,"runtime",fresh.Runtime));}
 }
 [STAThread]public static int Main(string[] args){Application.EnableVisualStyles();SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());var context=new ApplicationContext();var timer=new System.Windows.Forms.Timer{Interval=10};int code=0;timer.Tick+=async(s,e)=>{timer.Stop();try{await Run(args[0]);}catch(Exception error){code=1;File.WriteAllText(Path.Combine(args[0],"error.log"),error.ToString());}finally{context.ExitThread();}};timer.Start();Application.Run(context);timer.Dispose();return code;}
}
'@
$file=Join-Path $run 'CaptureFaultChecks.cs';[IO.File]::WriteAllText($file,$source,(New-Object Text.UTF8Encoding($false)));$compiler=Join-Path $env:WINDIR 'Microsoft.NET/Framework64/v4.0.30319/csc.exe';$exe=Join-Path $package 'CaptureFaultChecks.exe'
& $compiler /nologo /target:exe /platform:x64 ('/out:'+$exe) /r:System.Windows.Forms.dll /r:System.Drawing.dll ('/r:'+(Join-Path $package 'WebGAL.Video.exe')) ('/r:'+(Join-Path $package 'Microsoft.Web.WebView2.Core.dll')) ('/r:'+(Join-Path $package 'Microsoft.Web.WebView2.WinForms.dll')) $file
if($LASTEXITCODE -ne 0){throw 'Capture fault harness compile failed'}
$p=Start-Process -FilePath $exe -ArgumentList @(('"'+$run+'"')) -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $run 'stdout.log') -RedirectStandardError (Join-Path $run 'stderr.log');$watch=[Diagnostics.Stopwatch]::StartNew();while(-not $p.WaitForExit(1000)){if($watch.Elapsed.TotalSeconds -gt 60){& taskkill /PID $p.Id /T /F|Out-Null;throw "Own capture fault test exceeded 60s: $run"}};$p.WaitForExit();if($p.ExitCode -ne 0){throw "Capture fault test failed: $run"};Get-Content (Join-Path $run 'result.json') -Raw
